/**
 * The committed social-card image and legacy favicon (launch audit F-20):
 * generated by scripts/og-image.ts and checked here, so a stale, truncated or
 * mis-sized binary is a red test rather than a broken preview nobody sees.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { OG_IMAGE } from "../src/site/meta.js";
import { pngToIco } from "../scripts/og-image.js";

const PUBLIC = new URL("../public/", import.meta.url).pathname;
const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/** Width and height from a PNG's IHDR chunk. */
function pngSize(buf: Buffer): { width: number; height: number } {
  expect(buf.subarray(0, 8).equals(PNG_SIG)).toBe(true);
  expect(buf.subarray(12, 16).toString("latin1")).toBe("IHDR");
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

describe("public/og.png", () => {
  const og = readFileSync(`${PUBLIC}og.png`);

  it("is a PNG of exactly the size the meta tags declare", () => {
    expect(pngSize(og)).toEqual({ width: OG_IMAGE.width, height: OG_IMAGE.height });
    expect(OG_IMAGE.url.endsWith("/og.png")).toBe(true);
    expect(OG_IMAGE.type).toBe("image/png");
  });

  it("ends with IEND (not truncated) and stays small for a preview fetch", () => {
    expect(og.subarray(og.length - 8, og.length - 4).toString("latin1")).toBe("IEND");
    expect(og.length).toBeLessThan(150_000);
  });
});

describe("public/favicon.ico", () => {
  const ico = readFileSync(`${PUBLIC}favicon.ico`);

  it("is a single-image ICO whose entry points at a 32x32 PNG covering the rest of the file", () => {
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    expect(ico.readUInt16LE(4)).toBe(1);
    expect(ico.readUInt8(6)).toBe(32);
    expect(ico.readUInt8(7)).toBe(32);
    const len = ico.readUInt32LE(14);
    const off = ico.readUInt32LE(18);
    expect(off).toBe(22);
    expect(off + len).toBe(ico.length);
    expect(pngSize(ico.subarray(off))).toEqual({ width: 32, height: 32 });
  });

  it("pngToIco reproduces the committed header byte for byte", () => {
    const png = ico.subarray(22);
    expect(pngToIco(png, 32).equals(ico)).toBe(true);
  });
});
